class Solution {
public:
    int findNumber() {
        int ans = 0;
        for (int i = 0; i < 30; i++) {
            int a = commonBits(1 << i);
            int b = commonBits(1 << i);
            if (a > b) ans |= 1 << i;
        }
        return ans;
    }
};

